                    if 0 not in seq and len(set(seq)) == len(seq) and all(
                        [grid[r][c] for c in range(c0, c1 + 1)] == seq
                        for r in range(r0, r1 + 1)
                    ):
                        # Prefer the repeated strip with largest area.
                        candidates.append((len(seq) * (r1-r0+1), len(seq), r1-r0+1, r0, r1, c0, c1, seq))
    if not candidates:
        raise ValueError('No repeated palette strip')
    _, _, _, r0, r1, c0, c1, palette = max(candidates)
    key_cells = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)}

    # Find connected object of a palette color outside the palette strip.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color not in palette or (r,c) in key_cells or (r,c) in seen:
                continue
            stack = [(r,c)]
            seen.add((r,c))
            component = []
            while stack:
                rr,cc = stack.pop()
                component.append((rr,cc))
                for nr in range(rr-1, rr+2):
                    for nc in range(cc-1, cc+2):
                        if (0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen
                                and (nr,nc) not in key_cells and grid[nr][nc] == color):
                            seen.add((nr,nc))
                            stack.append((nr,nc))
            components.append((len(component), color, component))
    _, source_color, shape = max(components)

    minr = min(r for r,c in shape)
    maxr = max(r for r,c in shape)
    minc = min(c for r,c in shape)
    maxc = max(c for r,c in shape)
    shape_h = maxr - minr + 1
    index = palette.index(source_color)
    top = minr - index * shape_h

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        y = top + i * shape_h
        for r,c in shape:
            rr = y + r - minr
            if 0 <= rr < h:
                out[rr][c] = color
    return out
